  "upgrade.he_grenade_damage.description": "Erhöht HE-Explosionsschaden und Radius je Stufe um {value0}.",
  "upgrade.he_grenade_charges.name": "Granaten-Charges",
  "upgrade.he_grenade_charges.description": "Erhöht den HE-Vorrat je Stufe um {value0Unsigned} Charge. Regeneriert nacheinander im effektiven Cooldown; weitere Würfe setzen den Fortschritt nicht zurück. Wurfabstand: {heLockout}.",
  "upgrade.he_grenade_impact_fuse.name": "Aufschlagzünder",
  "upgrade.he_grenade_impact_fuse.description": "Die HE explodiert bei Kontakt mit lebenden gegnerischen Charakteren. Verbündete, Köder, Strukturen und Terrain lösen den Zünder nicht aus.",
  "upgrade.he_grenade_cluster.name": "Clustergranate",
  "upgrade.he_grenade_cluster.description": "Die Primärexplosion schleudert {value0Unsigned} explosive Splitter mit jeweils {heClusterDamage} Schaden und {heClusterRadius} Radius aus. Gestaffelte Zündung nach {heClusterFuse}.",
  "upgrade.he_grenade_cluster_mass.name": "Cluster-Masse",
  "upgrade.he_grenade_cluster_mass.description": "Erzeugt je Stufe {value0Unsigned} zusätzliche explosive Splitter mit kurzen und weiten Flugbahnen.",
  "upgrade.he_grenade_demolition_cluster.name": "Abriss-Cluster",
  "upgrade.he_grenade_demolition_cluster.description": "Der erste direkte Kontakt der HE mit einer feindlichen Struktur erzeugt {heDemolitionCount} Abriss-Splitter. Schaden pro Splitter nach Stufe: {heDemolitionDamage}. Radius: {heDemolitionRadius}; Zündung: {heDemolitionFuse}. Die HE fliegt weiter.",
  "upgrade.unlock_he_grenade.name": "HE-Granate",
  "upgrade.unlock_he_grenade.description": "Basis-Freischaltung für die HE-Granate im Utility-Slot.",
  "upgrade.unlock_time_bubble.name": "Time-Bubble",
  "upgrade.unlock_time_bubble.description": "Schaltet die Time-Bubble für den Utility-Slot frei. Eigene und verbündete Spieler bewegen sich frei; alle Projektile werden verlangsamt. Erneutes E löst die aktive Zeitblase auf. Der Cooldown beginnt erst mit ihrem Ende.",
  "upgrade.time_bubble_cooldown.name": "Time-Bubble: Cooldown",
  "upgrade.time_bubble_cooldown.description": "Verringert den Basis-Cooldown je Stufe um {value0Absolute}. Er beginnt erst mit dem Ende der Zeitblase.",
  "upgrade.time_bubble_overcharge.name": "Überladung",
  "upgrade.time_bubble_overcharge.description": "Erhöht die maximale Resonanz je Stufe um {value0Unsigned} auf {resonanceCapacities} Schaden.",
  "upgrade.time_bubble_resonance_flow.name": "Resonanzfluss",
  "upgrade.time_bubble_resonance_flow.description": "Jeder gespeicherte Resonanzpunkt erhöht die passive Adrenalin-Regeneration je Stufe um {flowPercent}. Der Bonus multipliziert bestehende Regenerationsboni, pausiert mit der normalen Regeneration und endet mit der Zeitblase. Resonanz wird nicht verbraucht.",
  "upgrade.time_bubble_radius.name": "Time-Bubble: Radius",
  "upgrade.time_bubble_radius.description": "Erhöht den Radius der Zeitblase je Stufe um {value0}.",
  "upgrade.time_bubble_prism_spiral.name": "Prismenspirale",
  "upgrade.time_bubble_resonance.name": "Resonanzspeicher",
  "upgrade.time_bubble_resonance.description": "Die Zeitblase speichert bis zu {value0Unsigned} Schaden berührender Projektile, Schüsse, Nahkampfangriffe und Explosionen. Eigene Angriffe und Prismenspirale zählen ebenfalls. Beim Ablauf oder Auflösen entlädt sie die gespeicherte Energie als Schaden im gesamten Blasenradius. Volle Ladung löst sie nicht vorzeitig aus.",
  "upgrade.time_bubble_focus.name": "Zeitfokus",
  "upgrade.time_bubble_focus.description": "Beim manuellen Auflösen mit E lenkst du alle fliegenden Projektile innerhalb der Zeitblase zum Mauszeiger um. Ihre Treffer werden dir zugerechnet; ihre Zielsuche bleibt aktiv.",
  "upgrade.time_bubble_prism_spiral.description": "Die Zeitblase feuert je Stufe alle {prismIntervalsMs} ms kleine zielsuchende Regenbogengeschosse. Die Abschussrichtung dreht sich in {prismRotationSeconds} s einmal rundum. Treffer verursachen {prismDamage} Grundschaden und verlangsamen Gegner um {prismSlowPercent} für {prismSlowSeconds} s. Die Zielsuche bevorzugt noch unbelegte Gegner und ignoriert Ziele innerhalb der aktiven Ursprungsblase. Auch diese Geschosse werden in Zeitblasen verlangsamt.",
  "upgrade.unlock_smoke_grenade.name": "Smoke-Granate",
  "upgrade.unlock_smoke_grenade.description": "Schaltet die Smoke-Granate für den Utility-Slot frei.",
  "upgrade.smoke_grenade_radius.name": "Upgrade Smoke-Granate: Radius",
  "upgrade.smoke_grenade_radius.description": "Erhöht den Radius der Rauchgranate je Stufe um {value0}.",
  "upgrade.smoke_grenade_duration.name": "Upgrade Smoke-Granate: Dauer",
  "upgrade.smoke_grenade_duration.description": "Erhöht die volle Standzeit der Rauchgranate je Stufe um {value0}; Ausbreitung und Ausklang bleiben gleich.",
  "upgrade.smoke_grenade_storm.name": "Upgrade Smoke-Granate: Gewittersturm",
  "upgrade.smoke_grenade_storm.description": "Gewittersturm verursacht {value0Unsigned} Schaden alle {smokeStormTick} s und lädt getroffene Gegner für {smokeChargeSeconds} s auf. Feste Hindernisse schirmen ab.",
  "upgrade.unlock_molotov_grenade.name": "Molotov",
