  "upgrade.stink_cloud_infection.name": "Verseuchung",
  "upgrade.stink_cloud_infection.description": "Primärwolkentreffer verseuchen Gegner für {value0Unsigned} je Stufe: {plagueDamage} Schaden alle {plagueTick} s. Erneuter Kontakt erneuert die volle Dauer.",
  "upgrade.stink_cloud_life_leech.name": "Lebensraub",
  "upgrade.stink_cloud_life_leech.description": "Verbündete heilen sich um zusätzlich {value0Unsigned} des tatsächlich verlorenen Gegnerlebens je Stufe, wenn sie Verseuchte treffen.",
  "upgrade.stink_cloud_spread.name": "Ausweitung",
  "upgrade.stink_cloud_spread.description": "Je Stufe {value0} Basis-Abklingzeit. Die Abklingzeit beginnt nach dem Wolkenende.",
  "upgrade.stink_cloud_combat_mode.name": "Kampfmodus",
  "upgrade.stink_cloud_combat_mode.description": "Während der Primärwolke je Stufe {value0} Laufgeschwindigkeit und {value1Unsigned} zusätzliche Schadensreduktion.",
  "upgrade.stink_cloud_pandemic.name": "Pandemie",
  "upgrade.stink_cloud_pandemic.description": "Verseuchte suchen gesunde Gegner im Umkreis von {plagueSearchRadius} px und hinterlassen Schleimspuren mit deinen Schleimspurwerten oder deren Grundwerten. Während der Verfolgung eines gesunden Ziels: +{plaguePursuitSpeed} Bewegungstempo und Immunität gegen Schleimschaden und -verlangsamung. Kontakt bis {contactGap} px Körperabstand überträgt die Seuche über zwei Generationen. Jede Generation erhält {plagueGenerationDuration} der vollen Dauer ihrer Vorgängergeneration, unabhängig von deren Restzeit. Die zweite Generation ist nicht ansteckend. Bosse verfolgen keine Seuchenziele.",
  "upgrade.stink_cloud_septic_shock.name": "Septischer Schock",
  "upgrade.stink_cloud_septic_shock.description": "Verseuchte erleiden durch allgemeine Verwundbarkeit {plagueVulnerability} mehr Schaden. Mehrere Verwundbarkeitsquellen stapeln sich nicht.",
  "upgrade.stink_cloud_slime_plague.name": "Schleimseuche",
  "upgrade.stink_cloud_slime_plague.description": "Verseuchte Tote erzeugen {value0Unsigned} Schleimbrocken je Stufe. Verwendet deine Schleimspurwerte oder deren Grundwerte. Addiert sich zu Schleimblüte; weitere Schleim-Todesketten benötigen Schleimblüte.",
  "upgrade.unlock_stink_cloud.name": "Stinkdrüsen",
  "upgrade.unlock_stink_cloud.description": "Schaltet Stinkdrüsen frei: {cloudSeconds} s aktive Wolke, {cloudRadius} px Radius, sofort und alle {cloudTick} s {cloudDamage} Schaden. Danach {cloudCooldown} s Abklingzeit.",
  "upgrade.translocator_cooldown.name": "Schnellere Rekalibrierung",
  "upgrade.translocator_cooldown.description": "{value0} Translocator-Cooldown pro Stufe.",
  "upgrade.translocator_phase_boost.name": "Phasenschub",
  "upgrade.translocator_phase_boost.description": "Nach Teleport und freundlichem Portaldurchgang: {value0} Bewegung pro Stufe für {phaseMoveSeconds} Sekunden. Der letzte vorhandene Effekt ersetzt den vorherigen.",
  "upgrade.translocator_phase_regeneration.name": "Phasenregeneration",
  "upgrade.translocator_phase_regeneration.description": "Nach Teleport und freundlichem Portaldurchgang: {value0Absolute} HP/s pro Stufe für {phaseRegenSeconds} Sekunden. Erneute Durchgänge erneuern den Effekt.",
  "upgrade.translocator_telefrag_radius.name": "Erweiterter Telefrag",
  "upgrade.translocator_telefrag_radius.description": "{value0} Telefrag-Radius pro Stufe. Erhöht weder Schaden noch Rückstoß.",
  "upgrade.translocator_portal_pair.name": "Portalpaar",
  "upgrade.translocator_portal_pair.description": "Der Teleport öffnet für {portalSeconds} Sekunden ein neutrales Portalpaar für Figuren und Angriffe. E schließt es; danach beginnt der Cooldown.",
  "upgrade.translocator_rift_collapse.name": "Risskollaps",
  "upgrade.translocator_rift_collapse.description": "Beide Portale ziehen beim Schließen Gegner heran und verlangsamen sie für {collapseSeconds} Sekunden. Radius: {collapseRadii} px. Pro Stufe: {value1} Slow.",
  "upgrade.translocator_portal_penetration.name": "Portaldurchschlag",
  "upgrade.translocator_portal_penetration.description": "Freundliche Angriffe erhalten nach dem Durchgang {value0} Schaden pro Stufe, einschließlich ihrer Schadensfolgen. Verschiedene Paare addieren sich einmalig ohne Obergrenze.",
  "upgrade.unlock_translocator.name": "Translocator",
  "upgrade.unlock_translocator.description": "Schaltet den Translocator für den Utility-Slot frei.",
  "upgrade.zeus_dynamo.name": "Dynamo",
  "upgrade.zeus_dynamo.description": "Jeder akzeptierte Dash verkürzt einen laufenden Zeus-Cooldown um {value0Unsigned}.",
